+                                        }
+                                    </div>
+                                </div>
+                            </div>
+                        }
+
+                        <!-- Add Task Form -->
+                        @if (_showFormForColumn == col)
+                        {
+                            <div class="card border-primary mt-2">
+                                <div class="card-body p-2">
+                                    <input type="text" class="form-control form-control-sm mb-1"
+                                           placeholder="Title" @bind="_newTitle" />
+                                    <input type="text" class="form-control form-control-sm mb-1"
+                                           placeholder="Assignee" @bind="_newAssignee" />
+                                    <select class="form-select form-select-sm mb-1" @bind="_newPriority">
+                                        <option value="High">High</option>
+                                        <option value="Medium">Medium</option>
+                                        <option value="Low">Low</option>
+                                    </select>
+                                    <input type="date" class="form-control form-control-sm mb-2"
+                                           @bind="_newDueDate" />
+                                    <div class="d-flex gap-1">
+                                        <button class="btn btn-primary btn-sm" @onclick="() => SaveTaskAsync(col)">Save</button>
+                                        <button class="btn btn-secondary btn-sm" @onclick="CancelForm">Cancel</button>
+                                    </div>
+                                </div>
+                            </div>
+                        }
+                        else
+                        {
+                            <button class="btn btn-outline-primary btn-sm w-100 mt-2"
+                                    @onclick="() => ShowForm(col)">
+                                + Add Task
+                            </button>
+                        }
+                    </div>
+                </div>
+            </div>
+        }
+    </div>
+}
+
+@code {
+    private static readonly string[] Columns = ["To Do", "In Progress", "Done"];
+
+    private List<TaskItem> _allTasks = [];
+    private List<TaskItem> _overdueTasks = [];
+    private bool _loading = true;
+    private string? _error;
+    private string _searchText = string.Empty;
+
+    // Form state
+    private string? _showFormForColumn;
+    private string _newTitle = string.Empty;
+    private string _newAssignee = string.Empty;
+    private string _newPriority = "Medium";
+    private DateTime _newDueDate = DateTime.Today.AddDays(7);
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            _allTasks = await TaskService.GetAllTasksAsync();
+            ComputeOverdue();
+        }
+        catch (Exception ex)
+        {
+            _error = $"Failed to load tasks: {ex.Message}";
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private void ComputeOverdue() =>
+        _overdueTasks = _allTasks.Where(t => t.DueDate.Date < DateTime.Today && t.Status != "Done").ToList();
+
+    private List<TaskItem> TasksForColumn(string status) =>
+        _allTasks.Where(t => t.Status == status).ToList();
+
+    private List<TaskItem> FilteredTasksForColumn(string status) =>
+        _allTasks
+            .Where(t => t.Status == status &&
+                        (string.IsNullOrWhiteSpace(_searchText) ||
+                         t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase)))
+            .ToList();
+
+    private async Task MoveTaskAsync(int taskId, string newStatus)
+    {
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var idx = _allTasks.FindIndex(t => t.Id == taskId);
+            if (idx >= 0)
+            {
+                var old = _allTasks[idx];
+                _allTasks[idx] = old with { Status = newStatus };
+            }
+            ComputeOverdue();
+        }
+        catch (Exception ex)
+        {
+            _error = $"Failed to move task: {ex.Message}";
+        }
+    }
+
+    private void ShowForm(string column)
+    {
+        _showFormForColumn = column;
+        _newTitle = string.Empty;
+        _newAssignee = string.Empty;
+        _newPriority = "Medium";
+        _newDueDate = DateTime.Today.AddDays(7);
+    }
+
+    private void CancelForm() => _showFormForColumn = null;
+
+    private async Task SaveTaskAsync(string column)
+    {
+        if (string.IsNullOrWhiteSpace(_newTitle))
+            return;
+
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(_newTitle.Trim(), _newAssignee.Trim(), _newPriority, _newDueDate);
+            // The service creates with a default status; override to match the column
+            _allTasks.Add(created with { Status = column });
+            if (created.Status != column)
+            {
+                await TaskService.UpdateTaskStatusAsync(created.Id, column);
+            }
+            ComputeOverdue();
+            _showFormForColumn = null;
+        }
+        catch (Exception ex)
+        {
+            _error = $"Failed to create task: {ex.Message}";
+        }
+    }
+
+    private static string PriorityClass(string priority) => priority switch
+    {
+        "High" => "bg-danger",
+        "Medium" => "bg-warning text-dark",
+        "Low" => "bg-success",
+        _ => "bg-secondary"
+    };
+}
